// Cloudflare Pages Function: /go/<offer> counts one click on a partner link, then redirects to it.
// The redirect table (lib/go-links.js) is generated by build.py from site.json "go_links".
//
// Counting is optional and stores no personal data: only the date, the offer slug and the
// page of this site the click came from. It needs a KV namespace bound to this Pages project
// as CLICKS (Cloudflare > Workers & Pages > KV > create "uaiwm-clicks"; then the Pages project >
// Settings > Bindings > add KV namespace, variable name CLICKS). Without the binding the links
// still redirect, they just aren't counted.
//
// Keys look like: 2026-11-24|systeme|/guides/quote-follow-up-system-for-tradespeople/

import LINKS from "../../lib/go-links.js";

const BOTS = /bot|crawl|spider|slurp|preview|facebookexternalhit|embedly|headless|lighthouse/i;

export async function onRequest({ params, request, env, waitUntil }) {
  const slug = String(params.offer || "").toLowerCase();
  const target = Object.prototype.hasOwnProperty.call(LINKS, slug) ? LINKS[slug] : null;
  if (!target) return Response.redirect(new URL("/recommended-tools/", request.url).toString(), 302);

  const ua = request.headers.get("User-Agent") || "";
  if (env.CLICKS && request.method === "GET" && !BOTS.test(ua)) {
    waitUntil(count(env.CLICKS, slug, request).catch(() => {}));
  }

  return new Response(null, {
    status: 302,
    headers: { Location: target, "Cache-Control": "no-store", "X-Robots-Tag": "noindex, nofollow" },
  });
}

async function count(kv, slug, request) {
  let from = "direct";
  const ref = request.headers.get("Referer");
  if (ref) {
    try {
      const u = new URL(ref);
      from = u.hostname.endsWith("understandaiwithme.com") ? u.pathname.slice(0, 200) : "external";
    } catch {
      from = "unknown";
    }
  }
  const key = `${new Date().toISOString().slice(0, 10)}|${slug}|${from}`;
  const n = parseInt((await kv.get(key)) || "0", 10) || 0;
  await kv.put(key, String(n + 1));
}
